import "server-only";
import fs from "node:fs";
import { boardYamlPath } from "./paths";
import { atomicWrite } from "./store";
import { STAGES, AREAS, BOARDS } from "./types";

// board.yaml config (handoff §4.5). The app both writes and reads this file, so the format is a
// constrained subset we control — no third-party YAML. `schema` is raised when the format changes
// and older files are migrated on load. Projects are generated by the app from EZ Binder jobs,
// deals and the software builds list (CC5/CC6/CC8); in CC2 there are none yet, so the list is
// empty but the shape is kept so later builds can fill it.

export const BOARD_SCHEMA = 1;

export type Project = {
  slug: string;
  name: string;
  group: "deal" | "gc_job" | "build" | "personal";
  deal_id?: string;
  ezbinder_id?: string;
  build_id?: string;
};

export type BoardConfig = {
  schema: number;
  stages: string[];
  boards: Record<string, { name: string }>;
  areas: string[];
  projects: Project[];
};

export function defaultConfig(): BoardConfig {
  return {
    schema: BOARD_SCHEMA,
    stages: [...STAGES],
    boards: {
      josh: { name: "Josh" },
      christine: { name: "Christine" },
      bishops: { name: "Bishops" },
    },
    areas: [...AREAS],
    projects: [],
  };
}

export function serializeConfig(cfg: BoardConfig): string {
  const lines: string[] = [];
  lines.push(`schema: ${cfg.schema}`);
  lines.push(`stages: [${cfg.stages.join(", ")}]`);
  lines.push("boards:");
  for (const key of Object.keys(cfg.boards)) {
    lines.push(`  ${key}: { name: ${cfg.boards[key].name} }`);
  }
  lines.push(`areas: [${cfg.areas.join(", ")}]`);
  lines.push("projects:            # generated by the app; do not edit by hand");
  for (const p of cfg.projects) {
    lines.push(`  - slug: ${p.slug}`);
    lines.push(`    name: ${p.name}`);
    lines.push(`    group: ${p.group}`);
    if (p.deal_id) lines.push(`    deal_id: ${p.deal_id}`);
    if (p.ezbinder_id) lines.push(`    ezbinder_id: ${p.ezbinder_id}`);
    if (p.build_id) lines.push(`    build_id: ${p.build_id}`);
  }
  return lines.join("\n") + "\n";
}

function flowList(raw: string): string[] {
  const inner = raw.trim().replace(/^\[/, "").replace(/\]$/, "").trim();
  if (!inner) return [];
  return inner.split(",").map((s) => s.trim()).filter(Boolean);
}

// Parse exactly the shape serializeConfig writes. Tolerant of inline comments after `#`.
export function parseConfig(text: string): BoardConfig {
  const cfg: BoardConfig = { schema: 0, stages: [], boards: {}, areas: [], projects: [] };
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  let section: "none" | "boards" | "projects" = "none";
  let current: Partial<Project> | null = null;
  const flushProject = () => {
    if (current && current.slug) cfg.projects.push(current as Project);
    current = null;
  };
  for (const rawLine of lines) {
    const line = rawLine.replace(/\t/g, "  ");
    if (line.trim() === "") continue;
    const topMatch = /^([A-Za-z0-9_]+):(.*)$/.exec(line);
    if (topMatch && !line.startsWith(" ")) {
      flushProject();
      const key = topMatch[1];
      const val = topMatch[2].replace(/#.*$/, "").trim();
      if (key === "schema") cfg.schema = Number(val) || 0;
      else if (key === "stages") cfg.stages = flowList(val);
      else if (key === "areas") cfg.areas = flowList(val);
      else if (key === "boards") section = "boards";
      else if (key === "projects") section = "projects";
      else section = "none";
      continue;
    }
    if (section === "boards") {
      const m = /^\s+([A-Za-z0-9_]+):\s*\{\s*name:\s*([^}]+?)\s*\}/.exec(line);
      if (m) cfg.boards[m[1]] = { name: m[2].trim() };
      continue;
    }
    if (section === "projects") {
      const slugM = /^\s*-\s*slug:\s*(.+)$/.exec(line);
      if (slugM) {
        flushProject();
        current = { slug: slugM[1].trim() };
        continue;
      }
      const kv = /^\s+([A-Za-z0-9_]+):\s*(.+)$/.exec(line);
      if (kv && current) {
        const k = kv[1];
        const v = kv[2].trim();
        if (k === "name") current.name = v;
        else if (k === "group") current.group = v as Project["group"];
        else if (k === "deal_id") current.deal_id = v;
        else if (k === "ezbinder_id") current.ezbinder_id = v;
        else if (k === "build_id") current.build_id = v;
      }
    }
  }
  flushProject();
  return cfg;
}

// Load board.yaml, creating a default on first run and migrating an older schema up (handoff §4.5).
export function loadConfig(): BoardConfig {
  const file = boardYamlPath();
  if (!fs.existsSync(file)) {
    const cfg = defaultConfig();
    atomicWrite(file, serializeConfig(cfg));
    return cfg;
  }
  const cfg = parseConfig(fs.readFileSync(file, "utf8"));
  if (cfg.schema < BOARD_SCHEMA) {
    cfg.schema = BOARD_SCHEMA;
    // Fixed structure fields are refreshed from the current constants on migration.
    cfg.stages = [...STAGES];
    cfg.areas = [...AREAS];
    if (Object.keys(cfg.boards).length === 0) cfg.boards = defaultConfig().boards;
    atomicWrite(file, serializeConfig(cfg));
  }
  return cfg;
}

export function saveConfig(cfg: BoardConfig): void {
  atomicWrite(boardYamlPath(), serializeConfig(cfg));
}
